local FlaskMaker = {}
local PRODUCTS = {
    iron_flask = { name = "Železna steklenica za livarstvo", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 165, prestige = 3, happiness = 2, description = "Železna steklenica za livarske potrebe." },
    bronze_flask = { name = "Bronasta steklenica za livarstvo", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 400, prestige = 5, happiness = 3, description = "Bronasta steklenica za varno shranjevanje." },
    silver_flask = { name = "Srebrna steklenica za livarstvo", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 970, prestige = 10, happiness = 4, description = "Srebrna steklenica za plemiške livarje." },
    gilded_flask = { name = "Pozlačena steklenica za livarstvo", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 2100, prestige = 19, happiness = 5, description = "Pozlačena steklenica za dvorne livarje." },
    jewel_set_flask = { name = "Draguljasta steklenica za livarstvo", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4500, prestige = 35, happiness = 7, description = "Draguljasta steklenica za kraljevske livarje." },
    royal_sovereign_flask = { name = "Kraljevski suverena steklenica za livarstvo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 9700, prestige = 67, happiness = 13, description = "Suverena steklenica z biseri za krono." },
}
local BUILDINGS = {
    flask_workshop = { name = "Steklenična delavnica", cost = { gold = 330, wood = 180, stone = 130, iron = 8 }, upkeep = 6, qualityBonus = 5 },
    flask_house = { name = "Steklenična hiša", cost = { gold = 1200, wood = 360, stone = 270, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_flask_atelier = { name = "Mojstrski steklenični atelje", cost = { gold = 3010, wood = 420, stone = 520, silver = 35, gold = 7 }, upkeep = 71, qualityBonus = 30 },
    sovereign_flask_palace = { name = "Suverena steklenična palača", cost = { gold = 13050, wood = 645, stone = 830, gold = 84, jewel = 19 }, upkeep = 255, qualityBonus = 55, prestigeBonus = 50 },
}
FlaskMaker.ironStock = 14; FlaskMaker.bronzeStock = 12; FlaskMaker.woodStock = 14; FlaskMaker.leatherStock = 10; FlaskMaker.silverStock = 8; FlaskMaker.goldStock = 6; FlaskMaker.jewelStock = 4; FlaskMaker.pearlStock = 4
FlaskMaker.productStock = {}; FlaskMaker.buildings = {}; FlaskMaker.maker = nil; FlaskMaker.activeMaking = {}; FlaskMaker.totalProducts = 0; FlaskMaker.dayTimer = 0
function FlaskMaker.init() FlaskMaker.ironStock=14; FlaskMaker.bronzeStock=12; FlaskMaker.woodStock=14; FlaskMaker.leatherStock=10; FlaskMaker.silverStock=8; FlaskMaker.goldStock=6; FlaskMaker.jewelStock=4; FlaskMaker.pearlStock=4; FlaskMaker.productStock={}; FlaskMaker.buildings={}; FlaskMaker.maker=nil; FlaskMaker.activeMaking={}; FlaskMaker.totalProducts=0; FlaskMaker.dayTimer=0; print("[FlaskMaker] Royal Flask Maker System initialized (6 products, 4 buildings)") end
function FlaskMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; FlaskMaker.maker={name=n or ("Stekleničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stekleničar najet: %s (spretnost: %d)",FlaskMaker.maker.name,s),"success") end; return true end
function FlaskMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function FlaskMaker.build(id) local ok,e=FlaskMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(FlaskMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function FlaskMaker.getQualityBonus() local b=0; for _,bd in ipairs(FlaskMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function FlaskMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and FlaskMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and FlaskMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and FlaskMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and FlaskMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and FlaskMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and FlaskMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and FlaskMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and FlaskMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #FlaskMaker.buildings==0 then return false,"Potrebna steklenična delavnica" end; if not FlaskMaker.maker then return false,"Potreben stekleničar" end; return true end
function FlaskMaker.make(pt,qty) qty=qty or 1; local ok,e=FlaskMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then FlaskMaker.ironStock=FlaskMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then FlaskMaker.bronzeStock=FlaskMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then FlaskMaker.woodStock=FlaskMaker.woodStock-d.woodCost*qty end; if d.leatherCost then FlaskMaker.leatherStock=FlaskMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then FlaskMaker.silverStock=FlaskMaker.silverStock-d.silverCost*qty end; if d.goldCost then FlaskMaker.goldStock=FlaskMaker.goldStock-d.goldCost*qty end; if d.jewelCost then FlaskMaker.jewelStock=FlaskMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then FlaskMaker.pearlStock=FlaskMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if FlaskMaker.maker then t=math.max(1,t-math.floor(FlaskMaker.maker.skill/13)) end; table.insert(FlaskMaker.activeMaking,{id="flask_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function FlaskMaker.completeMaking(m) local q=1.0+(FlaskMaker.getQualityBonus()/100); if FlaskMaker.maker then q=q+(FlaskMaker.maker.skill/140) end; q=math.min(2.5,q); FlaskMaker.productStock[m.productType]=(FlaskMaker.productStock[m.productType] or 0)+m.quantity; FlaskMaker.totalProducts=FlaskMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if FlaskMaker.maker then FlaskMaker.maker.itemsMade=FlaskMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then FlaskMaker.maker.skill=math.min(100,FlaskMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Steklenica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"flask.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function FlaskMaker.update(dt) if not _G.state then return end; FlaskMaker.dayTimer=FlaskMaker.dayTimer+dt; if FlaskMaker.dayTimer>=30 then FlaskMaker.dayTimer=0; for i=#FlaskMaker.activeMaking,1,-1 do local m=FlaskMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then FlaskMaker.completeMaking(m); table.remove(FlaskMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(FlaskMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if FlaskMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function FlaskMaker.getStats() return {ironStock=FlaskMaker.ironStock,bronzeStock=FlaskMaker.bronzeStock,woodStock=FlaskMaker.woodStock,leatherStock=FlaskMaker.leatherStock,silverStock=FlaskMaker.silverStock,goldStock=FlaskMaker.goldStock,jewelStock=FlaskMaker.jewelStock,pearlStock=FlaskMaker.pearlStock,productStock=FlaskMaker.productStock,numBuildings=#FlaskMaker.buildings,hasMaker=FlaskMaker.maker~=nil,makerName=FlaskMaker.maker and FlaskMaker.maker.name or "—",makerSkill=FlaskMaker.maker and FlaskMaker.maker.skill or 0,activeMaking=#FlaskMaker.activeMaking,totalProducts=FlaskMaker.totalProducts} end
return FlaskMaker
